}

function createErrorExit(programName, message) {
  return new CliParseExit(2, 'stderr', buildError(programName, message));
}

function missingValue(programName, option) {
  throw createErrorExit(programName, `argument ${option.label}: expected one argument`);
}

function parseOptionValue(option, rawValue, programName) {
  if (option.kind === 'string') {
    return rawValue;
  }

  const parsedValue = parsePythonInt(rawValue);
  if (parsedValue === null) {
    throw createErrorExit(programName, `argument ${option.label}: invalid int value: '${rawValue}'`);
  }

  return parsedValue;
}

function nextTokenCanBeUsedAsValue(nextToken) {
  if (nextToken === undefined || nextToken === '--') {
    return false;
  }

  const nextOption = resolveOption(extractOptionToken(nextToken));
  if (nextOption !== null) {
    return false;
  }

  if (String(nextToken).startsWith('-') && !looksLikeNegativeNumberToken(nextToken)) {
    return false;
  }

  return true;
}

function missingRequired(programName, values) {
  const missing = [];

  if (values.key === undefined) {
    missing.push('--key');
  }

  if (values.val === undefined) {
    missing.push('--val');
  }

  if (missing.length > 0) {
    throw createErrorExit(programName, `the following arguments are required: ${missing.join(', ')}`);
  }
}

function unrecognizedArguments(programName, extras) {
  if (extras.length > 0) {
    throw createErrorExit(programName, `unrecognized arguments: ${extras.join(' ')}`);
  }
}

export function parseArgs(argv, programName) {
  const values = {
    key: undefined,
    val: undefined,
  };
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = String(argv[index]);

    if (token === '--') {
      for (let extraIndex = index + 1; extraIndex < argv.length; extraIndex += 1) {
        extras.push(String(argv[extraIndex]));
      }
      break;
    }

    const optionToken = extractOptionToken(token);
    const explicitValue = extractExplicitValue(token);
    const option = resolveOption(optionToken);

    if (option === null) {
      extras.push(token);
      continue;
    }

    if (option.kind === 'help') {
      if (explicitValue !== null) {
        throw createErrorExit(
          programName,
          `argument ${option.label}: ignored explicit argument '${explicitValue}'`,
        );
      }

      throw createHelpExit(programName);
    }

    let rawValue = explicitValue;
    if (rawValue === null) {
      const nextToken = argv[index + 1];
      if (!nextTokenCanBeUsedAsValue(nextToken)) {
        missingValue(programName, option);
      }

      rawValue = String(nextToken);
      index += 1;
    }

    values[option.id] = parseOptionValue(option, rawValue, programName);
  }

  missingRequired(programName, values);
  unrecognizedArguments(programName, extras);

  return values;
}

const PYTHON_INT_PATTERN = /^[+-]?(?:\d+(?:_\d+)*)$/;
const NEGATIVE_NUMBER_TOKEN_PATTERN = /^-(?:\d+|\d*\.\d+)$/;

export function parsePythonInt(rawValue) {
  const value = String(rawValue);

  if (!PYTHON_INT_PATTERN.test(value)) {
    return null;
  }

  return Number.parseInt(value.replace(/_/g, ''), 10);
}

export function looksLikeNegativeNumberToken(token) {
  return NEGATIVE_NUMBER_TOKEN_PATTERN.test(String(token));
}

export function toPythonBool(value) {
  return value ? 'True' : 'False';
}

export function writePythonLine(text) {
  process.stdout.write(`${text}\n`);
}

export function buildUsage(programName) {
  return `usage: ${programName} [-h] --key KEY --val VAL`;
}

export function buildHelp(programName) {
  return `${buildUsage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --key KEY\n  --val VAL\n`;
}

export function buildError(programName, message) {
  return `${buildUsage(programName)}\n${programName}: error: ${message}\n`;
}

export function getProgramName(scriptPath) {
  if (!scriptPath) {
    return 'test6.mjs';
  }

  const normalizedPath = String(scriptPath).replace(/\\/g, '/');
  const segments = normalizedPath.split('/');
  const lastSegment = segments[segments.length - 1];
  return lastSegment || 'test6.mjs';
}
